window.OVA_CONTENT={"slug":"seccion-03-biotecnologia-y-decision-responsable","title":"Biotecnología y decisión responsable","minutes":50,"summary":"Diferencia PCR, clonación y edición génica y evalúa sus aplicaciones, límites y responsabilidades.","objective":"Analizar herramientas biotecnológicas según la pregunta, la evidencia y el riesgo asociado.","stages":[{"eyebrow":"Herramientas","title":"1. Una técnica para cada propósito","reading":"La PCR amplifica una región específica de ADN; la clonación genera copias de material genético, células u organismos según el contexto; CRISPR permite editar sitios determinados del material genético.","application":"Nombrar una técnica no demuestra que sea apropiada: primero debe definirse la pregunta productiva o diagnóstica.","activity":{"type":"match","question":"Relaciona técnica y función general.","pairs":[{"label":"PCR","value":"amplificar","option":"Amplificar una región de ADN"},{"label":"Clonación","value":"copias","option":"Obtener copias biológicas"},{"label":"CRISPR","value":"editar","option":"Modificar una secuencia específica"}],"answer":["amplificar","copias","editar"],"success":"La selección depende del propósito."}},{"eyebrow":"PCR","title":"2. Qué ocurre en una amplificación","reading":"En una PCR, ciclos de separación de hebras, unión de iniciadores y extensión permiten multiplicar una región. El resultado debe interpretarse con controles y respecto de una pregunta concreta.","application":"Una señal sin control puede reflejar contaminación, error de muestreo o amplificación no específica.","activity":{"type":"order","question":"Ordena el flujo de una prueba molecular responsable.","items":["Definir la región objetivo","Tomar y registrar la muestra","Amplificar con controles","Leer el resultado","Interpretar dentro del contexto"],"answer":[0,1,2,3,4],"success":"La trazabilidad comienza antes del laboratorio."}},{"eyebrow":"Aplicaciones","title":"3. Posibilidades en agroindustria","reading":"Las herramientas moleculares pueden apoyar identificación varietal, detección de organismos, selección asistida, trazabilidad y estudio de rasgos. Su utilidad depende de calidad de muestra, método y referencia.","application":"No reemplazan automáticamente controles de proceso, inspecciones, evaluación agronómica o análisis de inocuidad.","activity":{"type":"multi","question":"Selecciona aplicaciones plausibles.","options":["Identificación de material vegetal","Apoyo a la detección de un organismo objetivo","Estimación directa del rendimiento futuro sin ensayo agronómico","Comparación de perfiles genéticos"],"answer":[0,1,3],"success":"La biotecnología aporta evidencia específica, no una garantía total."}},{"eyebrow":"Bioseguridad","title":"4. Capacidad técnica y responsabilidad","reading":"Una tecnología puede ofrecer beneficios y, al mismo tiempo, generar incertidumbres ambientales, sociales o regulatorias. La evaluación responsable considera alcance, posibles efectos, reversibilidad, monitoreo y normas aplicables.","application":"El origen biológico o la precisión de una técnica no eliminan la necesidad de gestión del riesgo.","activity":{"type":"choice","question":"¿Qué criterio debe anteceder la adopción?","options":["Evaluar beneficios, riesgos, controles y regulación","Priorizar la precisión técnica y revisar regulación después del escalamiento","Adoptar primero y usar el monitoreo posterior como única barrera"],"answer":[0],"success":"Innovar exige evidencia y condiciones de uso."}},{"eyebrow":"Caso aplicado","title":"5. Edición para resistencia","reading":"Una empresa estudia material editado para resistencia a una enfermedad. Además del rasgo, debe analizar desempeño, estabilidad, interacción ambiental, acceso tecnológico y requisitos de autorización.","application":"La decisión debe documentar qué problema resuelve y cómo se vigilarán efectos no previstos.","activity":{"type":"choice","question":"¿Cuál evidencia es insuficiente por sí sola?","options":["Que el gen objetivo fue modificado","Que el material mantuvo el rasgo en varias generaciones y ambientes","Que existe un plan de monitoreo con indicadores definidos"],"answer":[0],"success":"Confirmar la edición no demuestra todo el comportamiento productivo."}},{"eyebrow":"Controles","title":"6. Resultados moleculares que pueden confiarse","reading":"Un ensayo molecular requiere controles positivos, negativos y de extracción. Cada uno permite reconocer fallas distintas, como ausencia de reacción o contaminación.","application":"Un lote no debe aceptarse o rechazarse con una señal cuya corrida carece de controles interpretables.","activity":{"type":"match","question":"Relaciona el control con la pregunta que ayuda a responder.","pairs":[{"label":"Control positivo","value":"funciona","option":"¿La reacción podía detectar el objetivo?"},{"label":"Control negativo","value":"contaminacion","option":"¿Apareció señal donde no debía?"},{"label":"Control de extracción","value":"muestra","option":"¿El proceso recuperó material interpretable?"}],"answer":["funciona","contaminacion","muestra"],"success":"Los controles convierten una señal en evidencia evaluable."}},{"eyebrow":"Escala","title":"7. Del laboratorio al proceso productivo","reading":"Un resultado prometedor en laboratorio debe atravesar pruebas de estabilidad, escala, desempeño, costos y cumplimiento regulatorio. El cambio de escala puede modificar variables críticas.","application":"La adopción responsable incluye criterios de detención y un plan de monitoreo posterior. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"multi","question":"¿Qué evidencias son pertinentes antes de escalar una biotecnología?","options":["Reproducibilidad en condiciones relevantes","Evaluación de riesgos y requisitos regulatorios","Desempeño técnico y económico a escala piloto","Popularidad de la técnica en redes sociales"],"answer":[0,1,2],"success":"Escalar exige integrar desempeño, riesgo, regulación y viabilidad."}},{"eyebrow":"Decisión","title":"8. Matriz de adopción responsable","reading":"Comparar alternativas exige una pregunta definida, evidencia de eficacia, riesgos, costos, capacidades y efectos sobre actores. Su interpretación exige comparar condiciones, escalas y registros, porque una observación aislada no demuestra causalidad ni permite predecir por sí sola el resultado productivo.","application":"Una matriz no decide automáticamente, pero hace explícitos los supuestos y permite documentar por qué se elige una alternativa.","activity":{"type":"order","question":"Ordena una evaluación de adopción biotecnológica.","items":["Precisar el problema y la población objetivo","Comparar alternativas y evidencia de eficacia","Evaluar riesgos, regulación y actores afectados","Probar a escala controlada con criterios de éxito","Decidir, monitorear y comunicar resultados"],"answer":[0,1,2,3,4],"success":"La adopción se justifica con una ruta transparente y revisable."}}],"number":"03","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};